#pragma once

#include <stdint.h>
#include <stdbool.h>

// ============================================================================
// Protocol Types
// ============================================================================

typedef enum {
    PROTOCOL_CAN = 0,
    PROTOCOL_RS485,
    PROTOCOL_ETHERCAT,
    PROTOCOL_COUNT
} ProtocolType;

// ============================================================================
// Motor Series Types
// ============================================================================

typedef enum {
    MOTOR_RMD_X = 0,  // Planetary
    MOTOR_RH,         // Harmonic
    MOTOR_CEM,        // Cycloid
    MOTOR_RMD_H,      // Direct Drive Hollow
    MOTOR_RMD_L,      // Direct Drive
    MOTOR_FL,         // Linear
    MOTOR_COUNT
} MotorSeries;

// ============================================================================
// Frame Types (from PROTOCOLS_CONTRACT.md)
// ============================================================================

typedef enum {
    STATUS_REPORT = 0x00,
    POSITION_CMD = 0x01,
    TORQUE_CMD = 0x02,
    VELOCITY_CMD = 0x03,
    HOME_CMD = 0x04,
    PARAM_READ = 0x05,
    PARAM_WRITE = 0x06,
    FAULT_RESET = 0x07,
    FIRMWARE_UPDATE = 0x08,
    RESERVED = 0x0A - 0xFF
} FrameType;

// ============================================================================
// Status Word Bit Definitions (from MOTOR_RMD_X_CONTRACT.md)
// ============================================================================

typedef struct {
    uint16_t ready : 1;
    uint16_t enabled : 1;
    uint16_t fault : 1;
    uint16_t homed : 1;
    uint16_t reserved : 12;
} StatusWord;

